select CARD_CLIENTS.rowid, CARD_CLIENTS.*,
sb_aca.getuserbyid(CARD_CLIENTS.OP_ID) as creat,sb_aca.getuserbyid(CARD_CLIENTS.NMOD_OPID) as modi,card_main.findfilial(CARD_CLIENTS.filial) as fil ,card_main.mainfind(CARD_CLIENTS.id) as TIP
 from CARD_CLIENTS where replace(CARD_CLIENTS.multi_acc,' ','')=REPLACE(:numb,' ','')

select DECODE(A.MESSTYPE,1,'NEW',2,'SUB CARD',3,'PROLONGATION',4,'REPLACE',12,'PIN ATTEMPTS CLEAR',6,'STATUS CHANGE',11,'RBSNUMBER CHANGE',7,'CONTRACT CLOSE',35,'CARDNAME CHANGE',5,'CREDIT LIMIT',13,'SEC WORD CHANGE') AS EMELIYYAT,
A.*,card_main.findfilial(a.filial) as fil,sb_aca.getuserbyid(a.OP_ID) as creat,sb_aca.getuserbyid(a.NMOD_OPID) as modi
from card_client_app A WHERE A.MESSTYPE<>1 AND A.multi_acc=:RBS and a.status in (1,4)

